export interface AccordionProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "onChange"> {
  /** Allow multiple panels open at once. */
  type?: "single" | "multiple";
  /** Initial open value(s). */
  defaultValue?: string | string[];
}

export interface AccordionItemProps extends React.HTMLAttributes<HTMLDivElement> {
  value: string;
}

export interface ActionTileProps
  extends Omit<React.ButtonHTMLAttributes<HTMLButtonElement>, "title"> {
  /** Icon shown in the accent container at the top of the tile. */
  icon: React.ReactNode;
  /** Tile title. */
  title: React.ReactNode;
  /** Supporting description below the title. */
  description?: React.ReactNode;
}

export interface AgentComposerProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "onSubmit"> {
  /** Controlled textarea value. */
  value: string;
  onValueChange: (value: string) => void;
  /** Called with the trimmed value on submit (Enter or send). */
  onSubmit: (value: string) => void;
  placeholder?: string;
  /** Toolbar content on the left (e.g. attach button). */
  leftActions?: React.ReactNode;
  /** Toolbar content on the right of the input, before the send button (e.g. model picker, mic). */
  rightActions?: React.ReactNode;
  /** Show the agent as busy — swaps send for a stop button. */
  loading?: boolean;
  onStop?: () => void;
  /** Max auto-grow height in px. */
  maxHeight?: number;
  /** Disable input + send. */
  disabled?: boolean;
}

export interface AlertProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "title"> {
  variant?: AlertVariant;
  /** Optional bold title above the body. */
  title?: React.ReactNode;
  /** Custom icon; defaults to a variant-appropriate one. */
  icon?: React.ReactNode;
  /** Hide the leading icon entirely. */
  hideIcon?: boolean;
}

export interface AvatarProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Role used to pick a default icon and styling when no image/initials given. */
  role?: MessageRole;
  /** Optional image URL; takes precedence over initials and the role icon. */
  src?: string;
  /** Explicit initials. If omitted, derived from `name`. */
  initials?: string;
  /** Display name — used to derive initials and the default aria-label. */
  name?: string;
  /** Corner style. `rounded` suits entity/person avatars, `circle` suits chat. */
  shape?: "circle" | "rounded";
  /** Accessible label / alt text. */
  alt?: string;
}

export interface BadgeProps extends React.HTMLAttributes<HTMLSpanElement> {
  /** Visual style. */
  variant?: BadgeVariant;
  /** Optional icon rendered before the label. */
  icon?: React.ReactNode;
}

export interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: ButtonVariant;
  size?: ButtonSize;
  /** Icon rendered before the label. */
  leftIcon?: React.ReactNode;
  /** Icon rendered after the label. */
  rightIcon?: React.ReactNode;
}

export interface CheckboxProps
  extends Omit<React.ButtonHTMLAttributes<HTMLButtonElement>, "onChange" | "value" | "type"> {
  /** Controlled checked state. */
  checked?: boolean;
  /** Initial state when uncontrolled. */
  defaultChecked?: boolean;
  /** Called with the next checked state. */
  onCheckedChange?: (checked: boolean) => void;
}

export interface ChecklistItemProps extends Omit<React.LiHTMLAttributes<HTMLLIElement>, "title"> {
  /** Whether the step is completed (shows a filled check + strikes the title). */
  done?: boolean;
  /** Step title. */
  title: React.ReactNode;
  /** Supporting description. */
  description?: React.ReactNode;
  /** Trailing action, e.g. a <Button>Connect</Button>. */
  action?: React.ReactNode;
}

export interface ChecklistProps extends React.HTMLAttributes<HTMLUListElement> {
  /** Show hairline dividers between items. */
  divided?: boolean;
}

export interface ChipProps extends React.HTMLAttributes<HTMLSpanElement> {
  /** Show a leading status dot. Pass a className to color it (e.g. "bg-success"). */
  dot?: boolean;
  /** Tailwind classes controlling the dot color (defaults to muted). */
  dotClassName?: string;
  /** When provided, renders a trailing remove button that calls this handler. */
  onRemove?: () => void;
  /** Accessible label for the remove button. */
  removeLabel?: string;
}

export interface CodeBlockProps extends React.HTMLAttributes<HTMLDivElement> {
  /** The raw source code to display. */
  code: string;
  /** Language label shown in the header (e.g. "ts", "python"). */
  language?: string;
  /** Hide the copy button. */
  hideCopy?: boolean;
}

export interface DialogProps {
  /** Whether the dialog is open. */
  open: boolean;
  /** Called when the dialog requests to close (overlay click / Escape). */
  onOpenChange: (open: boolean) => void;
  /** Panel content — compose DialogHeader/Title/Description/Footer. */
  children: React.ReactNode;
  /** Class overrides for the panel. */
  className?: string;
  /** Disable closing on overlay click / Escape. */
  dismissible?: boolean;
}

export interface FollowUpProps extends React.HTMLAttributes<HTMLDivElement> {
  /** The AI answer text. Ignored if `children` is provided. */
  answer?: React.ReactNode;
  /** The stated assumption; rendered as an editable chip. */
  assumption?: FollowUpAssumption;
  /** Called when the assumption chip is activated (to change the assumption). */
  onChangeAssumption?: () => void;
}

export interface GettingStartedPillProps
  extends Omit<React.ButtonHTMLAttributes<HTMLButtonElement>, "title"> {
  /** Leading label. */
  label?: React.ReactNode;
  /** Leading icon (defaults to a rocket). */
  icon?: React.ReactNode;
  /** Completed step count — combined with `total` to render "current of total". */
  current?: number;
  /** Total step count. */
  total?: number;
  /** Override the rendered progress text (takes precedence over current/total). */
  progressLabel?: React.ReactNode;
  /** Whether the associated panel is expanded — flips the chevron. */
  open?: boolean;
}

export interface GlobalNavProps extends React.HTMLAttributes<HTMLElement> {
  /** Leading content — brand mark, page heading, breadcrumbs. */
  left?: React.ReactNode;
  /** Centered content — typically a search field. */
  center?: React.ReactNode;
  /** Trailing content — notifications, account avatar, actions. */
  right?: React.ReactNode;
}

export interface IconButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  /** Accessible label — required since the button has no visible text. */
  "aria-label": string;
  variant?: IconButtonVariant;
  size?: IconButtonSize;
}

export interface InputBarProps
  extends Omit<React.TextareaHTMLAttributes<HTMLTextAreaElement>, "onSubmit" | "value" | "onChange"> {
  /** Controlled value of the input. */
  value: string;
  /** Called when the value changes. */
  onValueChange: (value: string) => void;
  /** Called with the trimmed value on submit (Enter or button). */
  onSubmit: (value: string) => void;
  /** Show the agent as busy — swaps the send button for a stop button. */
  loading?: boolean;
  /** Called when the stop button is pressed while `loading`. */
  onStop?: () => void;
  /** Max auto-grow height in px before scrolling. */
  maxHeight?: number;
}

export interface LinkButtonProps extends React.AnchorHTMLAttributes<HTMLAnchorElement> {
  /** Icon before the label. */
  leftIcon?: React.ReactNode;
  /** Icon after the label (e.g. an arrow for "Learn More"). */
  rightIcon?: React.ReactNode;
}

export interface MediaCardProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "title"> {
  /** Card title. */
  title?: React.ReactNode;
  /** Supporting description. */
  description?: React.ReactNode;
  /** Media node (image/video). Takes precedence over `image`. */
  media?: React.ReactNode;
  /** Image URL rendered as the media, when `media` isn't provided. */
  image?: string;
  /** Alt text for `image`. */
  imageAlt?: string;
  /** Layout: media on top (vertical) or beside the body (horizontal). */
  orientation?: "vertical" | "horizontal";
  /** Trailing content below the description (e.g. actions). */
  footer?: React.ReactNode;
}

export interface MenuItemProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  /** Leading icon. */
  icon?: React.ReactNode;
  /** Trailing content — shortcut hint or submenu chevron. */
  trailing?: React.ReactNode;
  /** Style as a destructive action. */
  destructive?: boolean;
}

export interface MessageProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Who authored the message. */
  role: MessageRole;
  /** Message text. Ignored if `children` is provided. */
  content?: string;
  /** True while the assistant is still streaming this message. */
  streaming?: boolean;
  /** Hide the avatar (e.g. for consecutive same-role messages). */
  hideAvatar?: boolean;
  /** Custom node rendered in place of the default avatar. */
  avatar?: React.ReactNode;
}

export interface ModularConsentProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "title"> {
  title: React.ReactNode;
  description?: React.ReactNode;
  /** The permissions the user can grant. */
  permissions: ConsentPermission[];
  denyLabel?: string;
  onDeny?: () => void;
  /** Optional middle action, e.g. "Always Allow". */
  secondaryLabel?: string;
  onSecondary?: (selectedIds: string[]) => void;
  allowLabel?: string;
  /** Called with the ids of the granted permissions. */
  onAllow?: (selectedIds: string[]) => void;
}

export interface NavPanelHeaderProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Trailing meta text, e.g. a count. */
  meta?: React.ReactNode;
}

export interface NavSectionProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "title"> {
  /** Section title. */
  title: React.ReactNode;
  /** Whether the section is collapsible (shows a chevron toggle). */
  collapsible?: boolean;
  /** Initial open state (collapsible sections). */
  defaultOpen?: boolean;
}

export interface NavItemProps extends React.AnchorHTMLAttributes<HTMLAnchorElement> {
  /** Marks the item as the current page. */
  active?: boolean;
}

export interface PageHeaderProps extends Omit<React.HTMLAttributes<HTMLElement>, "title"> {
  /** Page title (large heading). */
  title: React.ReactNode;
  /** Supporting description below the title. */
  description?: React.ReactNode;
  /** Badges / tags rendered in a row above the title. */
  badges?: React.ReactNode;
  /** Trailing actions aligned to the right of the title. */
  actions?: React.ReactNode;
}

export interface PopoverProps {
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  children: React.ReactNode;
}

export interface PopoverContentProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Horizontal alignment relative to the trigger. */
  align?: "start" | "end";
}

export interface ProgressProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Current value (0–max). Omit for an indeterminate bar. */
  value?: number;
  /** Maximum value. */
  max?: number;
  size?: ProgressSize;
  /** Class applied to the filled indicator (e.g. "bg-success"). */
  indicatorClassName?: string;
}

export interface RadioGroupProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "onChange"> {
  /** Controlled selected value. */
  value?: string;
  /** Initial value when uncontrolled. */
  defaultValue?: string;
  /** Called with the newly selected value. */
  onValueChange?: (value: string) => void;
  /** Accessible group label. */
  label?: string;
}

export interface RadioProps extends Omit<React.ButtonHTMLAttributes<HTMLButtonElement>, "value" | "type"> {
  /** The value this radio represents. */
  value: string;
}

export interface ReasoningProps extends React.HTMLAttributes<HTMLDivElement> {
  /** The reasoning / thinking text to reveal. */
  content: string;
  /** Whether reasoning is still streaming (shows a subtle pulse). */
  streaming?: boolean;
  /** Expanded by default. */
  defaultOpen?: boolean;
  /** Header label. */
  label?: string;
}

export interface RelatedPatternsGridProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Number of columns (default 2). */
  columns?: number;
}

export interface RelatedPatternCardProps
  extends Omit<React.AnchorHTMLAttributes<HTMLAnchorElement>, "title"> {
  /** Card title. */
  title: React.ReactNode;
  /** Supporting meta text, e.g. "Onboarding · Trust & Disclosure". */
  meta?: React.ReactNode;
}

export interface RichCheckboxOptionProps
  extends Omit<React.ButtonHTMLAttributes<HTMLButtonElement>, "onChange" | "value" | "type"> {
  /** Primary label. */
  label: React.ReactNode;
  /** Supporting secondary text. */
  description?: React.ReactNode;
  /** Controlled checked state. */
  checked?: boolean;
  /** Initial state when uncontrolled. */
  defaultChecked?: boolean;
  /** Called with the next checked state. */
  onCheckedChange?: (checked: boolean) => void;
}

export interface RichCheckboxGroupProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Accessible group label. */
  label?: string;
}

export interface RightSidebarAnchorProps extends React.AnchorHTMLAttributes<HTMLAnchorElement> {
  /** Marks the current in-view anchor. */
  active?: boolean;
}

export interface RightSidebarMetaProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Field name, e.g. "Stage". */
  label: React.ReactNode;
  /** Field value, e.g. "Onboarding". */
  value: React.ReactNode;
}

export interface SearchInputProps
  extends Omit<React.InputHTMLAttributes<HTMLInputElement>, "size"> {
  /** Custom leading icon (defaults to a magnifier). */
  icon?: React.ReactNode;
  /** Optional trailing content, e.g. a keyboard-shortcut hint. */
  trailing?: React.ReactNode;
  /** Wrapper className (the input fills the remaining space). */
  containerClassName?: string;
}

export interface SelectProps extends React.SelectHTMLAttributes<HTMLSelectElement> {
  /** Wrapper className (the chevron is positioned within it). */
  containerClassName?: string;
}

export interface SeparatorProps extends React.HTMLAttributes<HTMLDivElement> {
  orientation?: "horizontal" | "vertical";
  /** Purely visual (no semantic meaning for assistive tech). Defaults to true. */
  decorative?: boolean;
}

export interface SheetProps {
  /** Whether the sheet is open. */
  open: boolean;
  /** Called when the sheet requests to close (overlay click / Escape / close button). */
  onOpenChange: (open: boolean) => void;
  /** Which edge the sheet slides in from. */
  side?: SheetSide;
  /** Panel content — compose SheetHeader/Title/Description/Body/Footer. */
  children: React.ReactNode;
  /** Class overrides for the panel. */
  className?: string;
  /** Disable closing on overlay click / Escape. */
  dismissible?: boolean;
}

/**
 * Collapsed application sidebar — a narrow vertical icon rail. Compose a brand
 * mark, {@link SidebarItem}s, {@link SidebarSeparator}s, and a pinned `footer`:
 *
 * ```tsx
 * <Sidebar footer={<SidebarItem icon={<Settings />} label="Settings" />}>
 *   <BrandMark />
 *   <SidebarItem icon={<Home />} label="Home" active />
 *   <SidebarItem icon={<Sparkles />} label="Assistant" />
 * </Sidebar>
 * ```
 */
export interface SidebarProps extends React.HTMLAttributes<HTMLElement> {
  /** Content pinned to the bottom of the rail (e.g. settings). */
  footer?: React.ReactNode;
}

export interface SidebarItemProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  /** The icon to render. */
  icon: React.ReactNode;
  /** Accessible label + tooltip (rail is icon-only). */
  label: string;
  /** Marks the item as the current page. */
  active?: boolean;
}

export interface StreamingTextProps extends React.HTMLAttributes<HTMLSpanElement> {
  /** The text produced so far. */
  text: string;
  /** Show the blinking caret (typically true while tokens are still arriving). */
  streaming?: boolean;
}

export interface SuggestionsProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "onSelect"> {
  /** Convenience: render a chip per string and call `onSelect` on click. */
  items?: string[];
  /** Called with the selected suggestion text. */
  onSelect?: (value: string) => void;
}

export interface SwitchProps
  extends Omit<React.ButtonHTMLAttributes<HTMLButtonElement>, "onChange" | "value"> {
  /** Controlled on/off state. */
  checked?: boolean;
  /** Initial state when uncontrolled. */
  defaultChecked?: boolean;
  /** Called with the next state when toggled. */
  onCheckedChange?: (checked: boolean) => void;
  size?: SwitchSize;
}

export interface TabsProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "onChange"> {
  /** Controlled active tab value. */
  value?: string;
  /** Initial active tab when uncontrolled. */
  defaultValue?: string;
  /** Called with the newly selected value. */
  onValueChange?: (value: string) => void;
  orientation?: Orientation;
}

export interface TabsTriggerProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  /** Value linking this trigger to its TabsContent. */
  value: string;
}

export interface TabsContentProps extends React.HTMLAttributes<HTMLDivElement> {
  value: string;
}

export interface ThreadProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Change this whenever messages are added so the view re-pins to bottom. */
  autoScrollKey?: unknown;
  /** Disable the sticky "scroll to bottom" affordance. */
  hideScrollButton?: boolean;
}

export interface ToastProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "title"> {
  variant?: ToastVariant;
  title?: React.ReactNode;
  description?: React.ReactNode;
  /** Renders a close button that calls this handler. */
  onClose?: () => void;
}

export interface ToastProviderProps {
  children: React.ReactNode;
  /** Viewport placement. */
  placement?: "top" | "bottom";
}

export interface ToolCallProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "children"> {
  /** The tool call to render. */
  toolCall: ToolCallData;
  /** Whether the details are expanded initially. */
  defaultOpen?: boolean;
}

export interface TooltipProps extends Omit<React.HTMLAttributes<HTMLSpanElement>, "content"> {
  /** The tooltip text/content. */
  content: React.ReactNode;
  /** Which side of the trigger to show on. */
  side?: TooltipSide;
  /** The trigger element(s). */
  children: React.ReactNode;
}

export interface TypingIndicatorProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Accessible label announced to assistive tech. */
  label?: string;
}

