import { useState } from "react";
import type { Meta, StoryObj } from "@storybook/react";
import { Bell, Calendar, Home, ListChecks, Mic, Paperclip, Settings, Sparkles } from "lucide-react";
import {
  AgentComposer,
  Avatar,
  Badge,
  GlobalNav,
  IconButton,
  Message,
  Reasoning,
  SearchInput,
  Sidebar,
  SidebarItem,
  Suggestions,
  Thread,
  ToolCall,
} from "../index";

/**
 * A full agent chat screen assembled from Nucleux primitives — app shell +
 * transcript with reasoning, a tool call, streaming, suggestions, and the
 * agent composer.
 */
const meta = {
  title: "Examples/Agent Chat",
  parameters: { layout: "fullscreen" },
} satisfies Meta;

export default meta;
type Story = StoryObj<typeof meta>;

export const Default: Story = {
  render: () => {
    const [value, setValue] = useState("");
    return (
      <div className="flex h-screen flex-col bg-background">
        <GlobalNav
          left={<span className="text-base font-medium text-foreground">Nebula</span>}
          center={<SearchInput containerClassName="w-72" />}
          right={
            <>
              <IconButton aria-label="Notifications" size="lg">
                <Bell />
              </IconButton>
              <Avatar name="Eric" className="size-8" />
            </>
          }
        />

        <div className="flex min-h-0 flex-1">
          <Sidebar footer={<SidebarItem icon={<Settings />} label="Settings" />}>
            <SidebarItem icon={<Home />} label="Home" />
            <SidebarItem icon={<Sparkles />} label="Assistant" active />
            <SidebarItem icon={<Calendar />} label="Calendar" />
            <SidebarItem icon={<ListChecks />} label="Tasks" />
          </Sidebar>

          <main className="flex min-w-0 flex-1 flex-col">
            <Thread className="mx-auto w-full max-w-3xl">
              <Message role="user" content="Summarize the CPQ Q3 scope review and list the action items." />

              <div className="flex w-full max-w-3xl flex-col gap-2">
                <Reasoning
                  defaultOpen
                  content="The user wants a summary plus action items. I'll pull the transcript, extract decisions, then format owners and due dates."
                />
                <ToolCall
                  defaultOpen
                  toolCall={{
                    id: "t1",
                    name: "get_transcript",
                    status: "success",
                    args: { meetingId: "zuora-cpq-q3" },
                    result: { turns: 214, durationSec: 2700 },
                  }}
                />
              </div>

              <Message
                role="assistant"
                content="Here's the summary: the team aligned on a phased CPQ rollout, with pricing rules landing first. Three action items were captured."
              />
              <Message role="assistant" streaming content="Drafting the action item list" />
            </Thread>

            <div className="mx-auto w-full max-w-3xl space-y-3 p-4">
              <Suggestions
                items={["List action items", "Draft a follow-up email", "Show decisions"]}
                onSelect={setValue}
              />
              <AgentComposer
                value={value}
                onValueChange={setValue}
                onSubmit={() => setValue("")}
                leftActions={
                  <IconButton aria-label="Attach" size="sm">
                    <Paperclip />
                  </IconButton>
                }
                rightActions={
                  <>
                    <Badge variant="secondary">Opus 4.8</Badge>
                    <IconButton aria-label="Voice" size="sm">
                      <Mic />
                    </IconButton>
                  </>
                }
              />
            </div>
          </main>
        </div>
      </div>
    );
  },
};

import type { Meta, StoryObj } from "@storybook/react";
import { ArrowUpRight, Play, TrendingUp, Users } from "lucide-react";
import {
  Avatar,
  Badge,
  Button,
  CardAction,
  CardContainer,
  CardContent,
  CardDescription,
  CardDivider,
  CardHeader,
  CardTitle,
  LinkButton,
  Progress,
} from "../index";

/**
 * A gallery of card layouts ("card variations") — all built from the same
 * CardContainer primitive plus Badge, Avatar, Progress, and Button.
 */
const meta = {
  title: "Examples/Card Gallery",
  parameters: { layout: "padded" },
} satisfies Meta;

export default meta;
type Story = StoryObj<typeof meta>;

function StatCard() {
  return (
    <CardContainer>
      <CardContent className="space-y-2">
        <div className="flex items-center justify-between">
          <span className="text-sm text-muted-foreground">Meetings summarized</span>
          <TrendingUp className="size-4 text-success" />
        </div>
        <p className="text-3xl font-semibold tracking-tight text-foreground">128</p>
        <Badge variant="success">+12% this week</Badge>
      </CardContent>
    </CardContainer>
  );
}

function MediaCard() {
  return (
    <CardContainer className="overflow-hidden">
      <div className="relative flex aspect-video items-center justify-center bg-gradient-to-br from-slate-800 to-slate-950">
        <span className="inline-flex size-12 items-center justify-center rounded-full bg-background/95 text-foreground shadow-md">
          <Play className="size-5 translate-x-0.5 fill-current" />
        </span>
      </div>
      <CardContent className="space-y-1">
        <CardTitle>CPQ Q3 scope review</CardTitle>
        <CardDescription>45:00 · Summarized</CardDescription>
      </CardContent>
    </CardContainer>
  );
}

function ProgressCard() {
  return (
    <CardContainer>
      <CardHeader>
        <div>
          <CardTitle>Onboarding</CardTitle>
          <CardDescription>2 of 3 steps</CardDescription>
        </div>
        <Badge>66%</Badge>
      </CardHeader>
      <CardDivider />
      <CardContent className="space-y-3">
        <Progress value={66} aria-label="Onboarding progress" />
        <LinkButton rightIcon={<ArrowUpRight />}>Continue setup</LinkButton>
      </CardContent>
    </CardContainer>
  );
}

function TeamCard() {
  return (
    <CardContainer>
      <CardHeader>
        <div>
          <CardTitle>Workspace</CardTitle>
          <CardDescription>4 members</CardDescription>
        </div>
        <CardAction>Manage</CardAction>
      </CardHeader>
      <CardDivider />
      <CardContent className="flex items-center justify-between">
        <div className="flex -space-x-2">
          {["Eric Idle", "Zoe Ray", "Ada Lin", "Sam Poe"].map((n) => (
            <Avatar key={n} name={n} className="size-8 ring-2 ring-background" />
          ))}
        </div>
        <Button variant="secondary" size="sm" leftIcon={<Users className="size-4" />}>
          Invite
        </Button>
      </CardContent>
    </CardContainer>
  );
}

export const Default: Story = {
  render: () => (
    <div className="grid grid-cols-1 gap-6 sm:grid-cols-2 lg:grid-cols-4">
      <StatCard />
      <MediaCard />
      <ProgressCard />
      <TeamCard />
    </div>
  ),
};

import type { ReactNode } from "react";
import type { Meta, StoryObj } from "@storybook/react";
import { ArrowUpRight, ImageIcon, Play } from "lucide-react";
import {
  Avatar,
  Badge,
  Button,
  Chip,
  LinkButton,
  MediaCard,
} from "../index";

/**
 * The **Card Variation** family from Figma ("Card Variation 1…33") — every one
 * of them is the same anatomy: a media area with an overlaid *label*, a
 * *heading*, and a *description*. Rather than ship 22+ near-identical packages,
 * the whole family is expressed with a single {@link MediaCard} primitive via
 * its `media` slot, `orientation`, `footer`, and `title`/`description` props.
 *
 * This gallery reproduces the Figma pattern and then walks through the
 * meaningful, real-world permutations you get for free.
 */
const meta = {
  title: "Examples/Card Variations",
  parameters: { layout: "padded" },
} satisfies Meta;

export default meta;
type Story = StoryObj<typeof meta>;

/** A gradient "poster" with an optional overlaid label — the Figma media area. */
function Poster({
  label,
  labelVariant,
  icon,
  from = "from-slate-700",
  to = "to-slate-950",
}: {
  label?: ReactNode;
  labelVariant?: "chip" | "info" | "success" | "default";
  icon?: ReactNode;
  from?: string;
  to?: string;
}) {
  return (
    <div className={`relative flex size-full items-center justify-center bg-gradient-to-br ${from} ${to}`}>
      {icon && <span className="text-background/90">{icon}</span>}
      {label != null &&
