          <Badge variant={labelVariant} className="absolute left-3 top-3 shadow-sm">
            {label}
          </Badge>
        ) : (
          <Chip className="absolute left-3 top-3 shadow-sm">{label}</Chip>
        ))}
    </div>
  );
}

